int main()
{
	int times[MAX_SIZE];
	int times_size = 0;
	while(scanf("%d", &times[times_size++])) {
		if(getchar() != ',') break;
	}

	int m;
	scanf("%d", &m);

	printf("%d\n", getResult(times, times_size, m));

	return 0;
}

int getResult(int* times, int times_size, int m)
{
	int sum = 0;
	int max = 0;
	for(int i=0; i<times_size; i++) {
		sum += times[i];
		max = MAX(times[i], max);
	}

	// T的初始取值范围
	int low = 0;
	int high = sum - max;

	// 二分
	while(low <= high) {
		// 取中间值尝试
		int mid = (low + high) >> 1;

		if(check(mid, times, times_size, m)) {
			high = mid - 1;
		} else {
			low = mid + 1;
		}
	}

	return low;
}

